const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=type=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${type==='plus'?'<path d="M12 5v14M5 12h14"/>':type==='folder'?'<path d="M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v10H3z"/><path d="M12 16v-5m-2 2 2-2 2 2"/>':'<path d="m9 5 7 7-7 7"/>'}</svg>`;
export function welcomeHTML(pack,hasDraft,storageOK){const rounds=pack?.rounds||[],count=rounds.reduce((n,r)=>n+r.themes.reduce((m,t)=>m+t.questions.length,0),0);return `<div class="welcome-page"><div class="welcome-drop-overlay" aria-hidden="true"><div><strong>Отпустите .siq, чтобы открыть пак</strong><span>Он откроется сразу в редакторе</span></div></div><header class="welcome-header"><a class="brand" href="./" aria-label="SIGameMaker"><img class="brand-logo" src="./assets/logo-horizontal.png" alt="SIGameMaker"></a><span class="welcome-header-note">Для ваших хороших вечеров</span></header><main class="welcome-main"><div class="welcome-emblem" aria-hidden="true"><div><span>100</span><span>200</span><span>300</span></div><div><span>100</span><span>200</span><span>300</span></div><i>✦</i></div><p class="welcome-eyebrow">ВАША КОМПАНИЯ. ВАШИ ВОПРОСЫ.</p><h1>Соберите свою игру<span>.</span></h1><p class="welcome-intro">От первой идеи до готового пака для SIGame.<br>Начните с чистого листа или продолжите свою историю.</p><div class="welcome-actions"><button class="welcome-action welcome-create" data-action="create-pack"><span class="welcome-action-icon">${icon('plus')}</span><h2>Создать новый пак</h2><p>Ваши темы, вопросы и неожиданные открытия.</p><span class="welcome-action-link">Начать с идеи ${icon('arrow')}</span></button><button class="welcome-action welcome-open" data-action="import"><span class="welcome-action-icon">${icon('folder')}</span><h2>Открыть .siq</h2><p>Выберите файл или перетащите .siq в это окно.</p><span class="welcome-action-link">Выбрать файл ${icon('arrow')}</span></button></div>${hasDraft?`<section class="welcome-recent" aria-labelledby="recent-title"><h2 id="recent-title">Продолжить работу</h2><button class="welcome-draft" data-action="resume-pack"><span class="draft-thumbnail" aria-hidden="true">SI</span><span class="draft-description"><strong>${escape(pack.name)||'Без названия'}</strong><small>${rounds.length} раунд${rounds.length===1?'':rounds.length<5?'а':'ов'} · ${count} вопрос${count%10===1&&count%100!==11?'':count%10>=2&&count%10<=4&&(count%100<12||count%100>14)?'а':'ов'} · На этом устройстве</small></span><span class="draft-continue">Продолжить ${icon('arrow')}</span></button></section>`:''}<div class="welcome-explore"><span>Впервые здесь?</span><button data-action="open-demo">Посмотреть пример <span>↗</span></button><i>·</i><button data-action="help">Как это работает</button></div></main><footer class="welcome-footer"><span class="welcome-privacy">${storageOK?'Без регистрации. Черновик сохраняется в этом браузере.':'Автосохранение недоступно. Скачивайте .siq, чтобы сохранить работу.'}</span><span>Сделано для «Своей игры»</span></footer></div>`;}

// Accept file drops across the home screen, including its buttons and empty space.
export function installWelcomeDrop({target=document,enabled,onFile,onError}){
 let depth=0;
 const clear=()=>{depth=0;target.querySelector('.welcome-page')?.classList.remove('is-file-drag');};
 const fileDrag=ev=>Array.from(ev.dataTransfer?.types||[]).includes('Files');
 target.addEventListener('dragenter',ev=>{if(!enabled()||!fileDrag(ev))return;ev.preventDefault();depth++;target.querySelector('.welcome-page')?.classList.add('is-file-drag');});
 target.addEventListener('dragover',ev=>{if(!enabled()||!fileDrag(ev))return;ev.preventDefault();ev.dataTransfer.dropEffect='copy';});
 target.addEventListener('dragleave',ev=>{if(!fileDrag(ev))return;if(--depth<=0||!ev.relatedTarget)clear();});
 target.addEventListener('dragend',clear);
 target.addEventListener('drop',ev=>{
  const accept=enabled()&&fileDrag(ev);clear();if(!accept)return;ev.preventDefault();
  const files=Array.from(ev.dataTransfer.files);
  if(files.length!==1){onError('Перетащите один файл .siq');return;}
  if(!/\.siq$/i.test(files[0].name)){onError('Выберите файл пака в формате .siq');return;}
  onFile(files[0]);
 });
}
